type Gsel = d3.Selection<SVGGElement, unknown, null, undefined>;

const W = 1200;
const CX = W / 2;

const COLORS = {
  input: { fill: '#e3f2fd', stroke: '#1976d2' },
  layernorm: { fill: '#e8f5e9', stroke: '#22c55e' },
  rmsnorm: { fill: '#fff8e1', stroke: '#f59e0b' },
  batchnorm: { fill: '#fff3e0', stroke: '#f97316' },
  variance: { fill: '#fce4ec', stroke: '#e91e63' },
  scale: { fill: '#f3e5f5', stroke: '#7b1fa2' },
  output: { fill: '#e8f5e9', stroke: '#4caf50' },
  muted: 'var(--text-muted)' as string,
};

const BOX_H = 80;
const STEP_GAP = 420;
const BOX_TO_ROW = 280;
const SHAPE_GAP = 150;
const ARROW_MARGIN = 28;
const FOOTER_PAD = 60;

const GRID_ROWS = 4;
const GRID_COLS = 7;
const CELL = 34;
const SMALL_CELL = 25;

interface NCStep extends StepInfo {}
type NCVariant = 'overview' | 'norm_dims' | 'training_dynamics';

function lbl(
  g: Gsel, x: number, y: number, text: string,
  opts: { size?: number; weight?: string; color?: string; anchor?: 'start' | 'middle' | 'end'; font?: string } = {}
): void {
  drawLabel(g as Sel, x, y, text, opts);
}

function arrowH(
  g: Gsel, xFrom: number, xTo: number, y: number, color = '#94a3b8', margin = ARROW_MARGIN
): void {
  const dir = xTo >= xFrom ? 1 : -1;
  drawArrow(g as Sel, xFrom + dir * margin, y, xTo - dir * margin, y, { color });
}

function arrowV(
  g: Gsel, x: number, yFrom: number, yTo: number, color = '#94a3b8', margin = ARROW_MARGIN
): void {
  const dir = yTo >= yFrom ? 1 : -1;
  drawArrow(g as Sel, x, yFrom + dir * margin, x, yTo - dir * margin, { color });
}

function arrowL(
  g: Gsel, xFrom: number, yFrom: number, xTo: number, yTo: number, color = '#94a3b8', margin = ARROW_MARGIN
): void {
  // Horizontal-then-vertical elbow arrow with a single arrowhead at the destination.
  const xDir = xTo >= xFrom ? 1 : -1;
  const yDir = yTo >= yFrom ? 1 : -1;
  const x1 = xFrom + xDir * margin;
  const y2 = yTo - yDir * margin;
  const midX = (x1 + xTo) / 2;
  const arrowId = `arrow-l-${Math.random().toString(36).slice(2, 9)}`;
  const defs = g.selectAll('defs').data([null]).join('defs');
  defs
    .append('marker')
    .attr('id', arrowId)
    .attr('viewBox', '0 -5 10 10')
    .attr('refX', 8)
    .attr('refY', 0)
    .attr('markerWidth', 6)
    .attr('markerHeight', 6)
    .attr('orient', 'auto-start-reverse')
    .append('path')
    .attr('d', 'M 0,-5 L 10,0 L 0,5')
    .attr('fill', color);
  g.append('path')
    .attr('d', `M ${x1} ${yFrom} L ${midX} ${yFrom} L ${midX} ${y2} L ${xTo} ${yTo}`)
    .attr('fill', 'none')
    .attr('stroke', color)
    .attr('stroke-width', 1.5)
    .attr('stroke-linejoin', 'round')
    .attr('marker-end', `url(#${arrowId})`);
}

function startGroup(g: Gsel, cls: string, step: number): Gsel {
  return g.append('g').attr('class', `step-node ${cls}`).attr('data-step', String(step));
}

function stepHeader(
  g: Gsel, cx: number, y: number, sn: number, title: string, formula: string,
  fill: string, stroke: string, width = W - 80
): number {
  const w = width;
  g.append('rect').attr('x', cx - w / 2).attr('y', y).attr('width', w).attr('height', BOX_H)
    .attr('rx', 8).attr('fill', fill).attr('stroke', stroke).attr('stroke-width', 1.5);
  g.append('circle').attr('cx', cx - w / 2 + 28).attr('cy', y + BOX_H / 2)
    .attr('r', 16).attr('fill', stroke);
  lbl(g, cx - w / 2 + 28, y + BOX_H / 2 + 1, String(sn), { size: 14, weight: '700', color: '#fff' });
  lbl(g, cx - w / 2 + 56, y + BOX_H / 2 - 7, title, { size: 15, weight: '600', color: 'var(--text)', anchor: 'start' });
  lbl(g, cx - w / 2 + 56, y + BOX_H / 2 + 14, formula, { size: 10, color: 'var(--text-muted)', font: 'monospace', anchor: 'start' });
  return y + BOX_H;
}

function shapeEq(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  const w = Math.max(text.length * 7.5 + 56, 380);
  const h = 36;
  g.append('rect').attr('x', cx - w / 2).attr('y', cy - h / 2).attr('width', w).attr('height', h)
    .attr('rx', 4).attr('fill', 'var(--surface)').attr('stroke', color).attr('stroke-width', 0.5).attr('opacity', 0.9);
  lbl(g, cx, cy + 1, text, { size: 11, color, font: 'monospace' });
}

function opBox(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  const w = text.length * 10 + 28;
  const h = 36;
  g.append('rect').attr('x', cx - w / 2).attr('y', cy - h / 2).attr('width', w).attr('height', h)
    .attr('rx', 6).attr('fill', '#fff').attr('stroke', color).attr('stroke-width', 1.5);
  lbl(g, cx, cy + 1, text, { size: 13, weight: '700', color });
}

function smallNote(g: Gsel, x: number, y: number, text: string, color: string, anchor: 'start' | 'middle' | 'end' = 'start'): void {
  lbl(g, x, y, text, { size: 10, color, anchor, font: 'monospace' });
}

function sampleNote(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  const w = Math.max(text.length * 6.8 + 40, 240);
  const h = 24;
  g.append('rect')
    .attr('x', cx - w / 2).attr('y', cy - h / 2).attr('width', w).attr('height', h)
    .attr('rx', 4).attr('fill', 'var(--surface)').attr('stroke', color)
    .attr('stroke-width', 0.5).attr('opacity', 0.88);
  lbl(g, cx, cy + 1, text, { size: 10, color, font: 'monospace' });
}

function paramSummary(g: Gsel, cx: number, y: number, items: string[]): number {
  const w = W - 160;
  const h = 36;
  g.append('rect').attr('x', cx - w / 2).attr('y', y).attr('width', w).attr('height', h)
    .attr('rx', 6).attr('fill', 'var(--surface)').attr('stroke', 'var(--border)').attr('stroke-width', 0.5);
  const segW = w / items.length;
  items.forEach((item, i) => {
    lbl(g, cx - w / 2 + segW * (i + 0.5), y + h / 2 + 1, item, { size: 10, color: COLORS.muted, font: 'monospace' });
  });
  return y + h;
}

function makeStep(
  id: number, sl: string, l: string, f: string, ex: string,
  sg: string, c: string, fl: string, cl?: string[]
): NCStep {
  return { id, label: l, shortLabel: sl, formula: f, explanation: ex,
    code: { title: l, lines: cl || [`# ${f}`] }, svgGroup: sg, color: c, fill: fl };
}

function drawValueGrid(
  g: Gsel, cx: number, cy: number, rows: number, cols: number, cellSize: number,
  values: number[], transform: (v: number) => number, inColor: string, outColor: string,
  decimals = 1
): void {
  const w = cols * cellSize;
  const h = rows * cellSize;
  const x0 = cx - w / 2;
  const y0 = cy - h / 2;
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const idx = r * cols + c;
      const v = values[idx % values.length];
      const out = transform(v);
      const rx = x0 + c * cellSize;
      const ry = y0 + r * cellSize;
      const isZero = Math.abs(out) < 0.01;
      const isNeg = out < 0;
      g.append('rect').attr('x', rx).attr('y', ry).attr('width', cellSize - 1).attr('height', cellSize - 1)
        .attr('fill', isZero ? '#fef2f2' : isNeg ? '#fff7ed' : '#f0fdf4')
        .attr('stroke', '#e2e8f0').attr('stroke-width', 0.3);
      const text = out.toFixed(decimals);
      const fontSize = cellSize >= 28 ? 10 : cellSize >= 22 ? 9 : 8;
      lbl(g, rx + cellSize / 2, ry + cellSize / 2, text, {
        size: fontSize, color: isZero ? '#f87171' : isNeg ? '#f97316' : outColor,
      });
    }
  }
  g.append('rect').attr('x', x0 - 1).attr('y', y0 - 1).attr('width', w + 2).attr('height', h + 2)
    .attr('fill', 'none').attr('stroke', inColor).attr('stroke-width', 1).attr('rx', 2);
}

function drawInputGrid(
  g: Gsel, cx: number, cy: number, rows: number, cols: number, cellSize: number,
  values: number[], color: string
): void {
  const w = cols * cellSize;
  const h = rows * cellSize;
  const x0 = cx - w / 2;
  const y0 = cy - h / 2;
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const idx = r * cols + c;
      const v = values[idx % values.length];
      const rx = x0 + c * cellSize;
      const ry = y0 + r * cellSize;
      const isNeg = v < 0;
      g.append('rect').attr('x', rx).attr('y', ry).attr('width', cellSize - 1).attr('height', cellSize - 1)
        .attr('fill', isNeg ? '#fff3e0' : '#e3f2fd').attr('stroke', '#e2e8f0').attr('stroke-width', 0.3);
      lbl(g, rx + cellSize / 2, ry + cellSize / 2, v.toFixed(1), {
        size: cellSize >= 24 ? 10 : 9, color: isNeg ? '#f97316' : color,
      });
    }
  }
  g.append('rect').attr('x', x0 - 1).attr('y', y0 - 1).attr('width', w + 2).attr('height', h + 2)
    .attr('fill', 'none').attr('stroke', color).attr('stroke-width', 1).attr('rx', 2);
}

function drawNormAxisGrid(
  g: Gsel, cx: number, cy: number, rows: number, cols: number, cellSize: number,
  values: number[], highlightMode: 'row' | 'col', highlightIdx: number,
  highlightColor: string, label: string
): void {
  const w = cols * cellSize;
  const h = rows * cellSize;
  const x0 = cx - w / 2;
  const y0 = cy - h / 2;
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const idx = r * cols + c;
      const v = values[idx % values.length];
      const rx = x0 + c * cellSize;
      const ry = y0 + r * cellSize;
      const isHighlighted = highlightMode === 'row' ? r === highlightIdx : c === highlightIdx;
      g.append('rect').attr('x', rx).attr('y', ry).attr('width', cellSize - 1).attr('height', cellSize - 1)
        .attr('fill', isHighlighted ? '#f0fdf4' : '#f8fafc')
        .attr('stroke', '#e2e8f0').attr('stroke-width', 0.3);
      if (isHighlighted) {
        g.append('rect').attr('x', rx).attr('y', ry).attr('width', cellSize - 1).attr('height', cellSize - 1)
          .attr('fill', highlightColor).attr('opacity', 0.35);
      }
      lbl(g, rx + cellSize / 2, ry + cellSize / 2, v.toFixed(1), {
        size: cellSize >= 24 ? 10 : 9, color: isHighlighted ? '#1e293b' : '#64748b',
      });
    }
  }
  g.append('rect').attr('x', x0 - 1).attr('y', y0 - 1).attr('width', w + 2).attr('height', h + 2)
    .attr('fill', 'none').attr('stroke', '#94a3b8').attr('stroke-width', 1).attr('rx', 2);
  lbl(g, cx, y0 + h + 14, label, { size: 10, color: highlightColor, weight: '600' });
}

function drawFormulaStack(
  g: Gsel, cx: number, cy: number, steps: { text: string; color: string }[], boxW = 260, boxH = 22, gap = 8
): void {
  const totalH = steps.length * boxH + (steps.length - 1) * gap;
  const startY = cy - totalH / 2;
  for (let i = 0; i < steps.length; i++) {
    const y = startY + i * (boxH + gap) + boxH / 2;
    g.append('rect').attr('x', cx - boxW / 2).attr('y', y - boxH / 2).attr('width', boxW).attr('height', boxH)
      .attr('rx', 4).attr('fill', '#fff').attr('stroke', steps[i].color).attr('stroke-width', 1.5);
    lbl(g, cx, y + 1, steps[i].text, { size: 10, color: steps[i].color, font: 'monospace' });
    if (i < steps.length - 1) {
      arrowV(g, cx, y + boxH / 2, y + boxH / 2 + gap, steps[i].color, 4);
    }
  }
}

function scalarBlock(g: Gsel, cx: number, cy: number, value: string, label: string, color: string): void {
  const w = 90;
  const h = 48;
  g.append('rect').attr('x', cx - w / 2).attr('y', cy - h / 2).attr('width', w).attr('height', h)
    .attr('rx', 4).attr('fill', '#fff').attr('stroke', color).attr('stroke-width', 1.5);
  lbl(g, cx, cy - 5, value, { size: 12, weight: '700', color });
  lbl(g, cx, cy + 10, label, { size: 9, color: 'var(--text-muted)', font: 'monospace' });
}

