function renderOverview(
  g: Gsel, yStart: number, seqLen: number, dModel: number
): { steps: NCStep[]; y: number } {
  const steps: NCStep[] = [];
  let y = yStart;

  // Step 1: Input Activations
  {
    const stepId = 1;
    const gs = startGroup(g, 'step-input', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Input Activations', `x [${seqLen}, ${dModel}]`,
      COLORS.input.fill, COLORS.input.stroke);
    const rowY = hBottom + BOX_TO_ROW;
    const gridH = GRID_ROWS * CELL;
    lbl(gs, CX, rowY - gridH / 2 - 20, 'x', { size: 12, weight: '700', color: COLORS.input.stroke });
    drawInputGrid(gs, CX, rowY, GRID_ROWS, GRID_COLS, CELL, SAMPLE_MATRIX, COLORS.input.stroke);
    smallNote(gs, CX + GRID_COLS * CELL / 2 + 14, rowY - 16, 'blue = positive', COLORS.input.stroke, 'start');
    smallNote(gs, CX + GRID_COLS * CELL / 2 + 14, rowY + 4, 'orange = negative', '#f97316', 'start');
    shapeEq(gs, CX, rowY + gridH / 2 + SHAPE_GAP, `x [${seqLen}, ${dModel}]`, COLORS.input.stroke);
    sampleNote(gs, CX, rowY + gridH / 2 + SHAPE_GAP + 36, 'same input applied to all 3 norms', COLORS.input.stroke);
    y = rowY + gridH / 2 + SHAPE_GAP + 60 + STEP_GAP;
    steps.push(makeStep(stepId, 'Input', 'Input Activations', `x [${seqLen}, ${dModel}]`,
      'Input hidden states shared by all normalization methods.', 'step-input',
      COLORS.input.stroke, COLORS.input.fill));
  }

  // Step 2: Normalization Axes Comparison
  {
    const stepId = 2;
    const gs = startGroup(g, 'step-axes', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Normalization Axes Comparison',
      'LayerNorm vs RMSNorm vs BatchNorm', COLORS.layernorm.fill, COLORS.layernorm.stroke);
    const rowY = hBottom + BOX_TO_ROW;
    const cellSize = 22;
    const gridH = GRID_ROWS * cellSize;
    const xLeft = CX - 360;
    const xMid = CX;
    const xRight = CX + 360;

    lbl(gs, xLeft, rowY - gridH / 2 - 32, 'LayerNorm', { size: 12, weight: '700', color: COLORS.layernorm.stroke });
    drawNormAxisGrid(gs, xLeft, rowY, GRID_ROWS, GRID_COLS, cellSize, SAMPLE_MATRIX, 'row', 2,
      COLORS.layernorm.stroke, 'normalize over d_model (per token)');

    lbl(gs, xMid, rowY - gridH / 2 - 32, 'RMSNorm', { size: 12, weight: '700', color: COLORS.rmsnorm.stroke });
    drawNormAxisGrid(gs, xMid, rowY, GRID_ROWS, GRID_COLS, cellSize, SAMPLE_MATRIX, 'row', 2,
      COLORS.rmsnorm.stroke, 'normalize over d_model (per token)');

    lbl(gs, xRight, rowY - gridH / 2 - 32, 'BatchNorm', { size: 12, weight: '700', color: COLORS.batchnorm.stroke });
    drawNormAxisGrid(gs, xRight, rowY, GRID_ROWS, GRID_COLS, cellSize, SAMPLE_MATRIX, 'col', 3,
      COLORS.batchnorm.stroke, 'normalize over batch/seq (per feature)');

    shapeEq(gs, CX, rowY + gridH / 2 + SHAPE_GAP,
      'LN/RMS: per-token stats (row) | BN: per-feature stats (column)', COLORS.layernorm.stroke);
    sampleNote(gs, CX, rowY + gridH / 2 + SHAPE_GAP + 40,
      'axis choice = key differentiator between norms', COLORS.layernorm.stroke);
    y = rowY + gridH / 2 + SHAPE_GAP + 60 + STEP_GAP;
    steps.push(makeStep(stepId, 'Axes', 'Normalization Axes Comparison',
      'LayerNorm vs RMSNorm vs BatchNorm axes',
      'Different norms reduce statistics over different tensor axes.', 'step-axes',
      COLORS.layernorm.stroke, COLORS.layernorm.fill));
  }

  // Step 3: Computation Comparison
  {
    const stepId = 3;
    const gs = startGroup(g, 'step-compute', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Computation Comparison',
      'key formulas side by side', COLORS.scale.fill, COLORS.scale.stroke);
    const rowY = hBottom + BOX_TO_ROW;
    const xLeft = CX - 360;
    const xMid = CX;
    const xRight = CX + 360;

    const cardW = 330;
    const cardH = 210;
    const cardY = rowY;
    const stackCy = cardY + 28;

    // LayerNorm card
    gs.append('rect').attr('x', xLeft - cardW / 2).attr('y', cardY - cardH / 2).attr('width', cardW).attr('height', cardH)
      .attr('rx', 8).attr('fill', '#fff').attr('stroke', COLORS.layernorm.stroke).attr('stroke-width', 1.5);
    lbl(gs, xLeft, cardY - cardH / 2 + 22, 'LayerNorm', { size: 13, weight: '700', color: COLORS.layernorm.stroke });
    drawFormulaStack(gs, xLeft, stackCy, [
      { text: 'μ = mean(x)', color: COLORS.layernorm.stroke },
      { text: 'σ² = var(x)', color: COLORS.variance.stroke },
      { text: 'x̂ = (x-μ) / √(σ²+ε)', color: COLORS.layernorm.stroke },
      { text: 'γ·x̂ + β', color: COLORS.scale.stroke },
    ], 260, 20, 8);

    // RMSNorm card
    gs.append('rect').attr('x', xMid - cardW / 2).attr('y', cardY - cardH / 2).attr('width', cardW).attr('height', cardH)
      .attr('rx', 8).attr('fill', '#fff').attr('stroke', COLORS.rmsnorm.stroke).attr('stroke-width', 1.5);
    lbl(gs, xMid, cardY - cardH / 2 + 22, 'RMSNorm', { size: 13, weight: '700', color: COLORS.rmsnorm.stroke });
    drawFormulaStack(gs, xMid, stackCy, [
      { text: 'x²', color: COLORS.rmsnorm.stroke },
      { text: 'mean(x²)', color: COLORS.variance.stroke },
      { text: 'RMS = √(·+ε)', color: COLORS.rmsnorm.stroke },
      { text: 'x̂ = x / RMS', color: COLORS.rmsnorm.stroke },
      { text: 'γ·x̂', color: COLORS.scale.stroke },
    ], 260, 20, 8);

    // BatchNorm card
    gs.append('rect').attr('x', xRight - cardW / 2).attr('y', cardY - cardH / 2).attr('width', cardW).attr('height', cardH)
      .attr('rx', 8).attr('fill', '#fff').attr('stroke', COLORS.batchnorm.stroke).attr('stroke-width', 1.5);
    lbl(gs, xRight, cardY - cardH / 2 + 22, 'BatchNorm', { size: 13, weight: '700', color: COLORS.batchnorm.stroke });
    drawFormulaStack(gs, xRight, stackCy, [
      { text: 'μ_B = mean_B(x)', color: COLORS.batchnorm.stroke },
      { text: 'σ²_B = var_B(x)', color: COLORS.variance.stroke },
      { text: 'x̂ = (x-μ_B) / √(σ²_B+ε)', color: COLORS.batchnorm.stroke },
      { text: 'γ·x̂ + β', color: COLORS.scale.stroke },
    ], 260, 20, 8);

    shapeEq(gs, CX, cardY + cardH / 2 + SHAPE_GAP + 10,
      'RMSNorm skips mean subtraction → ~33% fewer ops', COLORS.rmsnorm.stroke);
    sampleNote(gs, CX, cardY + cardH / 2 + SHAPE_GAP + 50,
      'LN/BN: 2×d_model params (γ+β) | RMS: d_model params (γ only)', COLORS.scale.stroke);
    y = cardY + cardH / 2 + SHAPE_GAP + 80 + STEP_GAP;
    steps.push(makeStep(stepId, 'Compute', 'Computation Comparison',
      'LayerNorm, RMSNorm, BatchNorm formulas',
      'Compare the exact sequence of operations for each normalization method.', 'step-compute',
      COLORS.scale.stroke, COLORS.scale.fill));
  }

  // Step 4: Usage Summary
  {
    const stepId = 4;
    const gs = startGroup(g, 'step-usage', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Usage Summary', 'when to use each norm',
      COLORS.output.fill, COLORS.output.stroke);
    const rowY = hBottom + BOX_TO_ROW;
    const cardW = 320;
    const cardH = 155;
    const xLeft = CX - 380;
    const xMid = CX;
    const xRight = CX + 380;

    gs.append('rect').attr('x', xLeft - cardW / 2).attr('y', rowY - cardH / 2).attr('width', cardW).attr('height', cardH)
      .attr('rx', 8).attr('fill', COLORS.layernorm.fill).attr('stroke', COLORS.layernorm.stroke).attr('stroke-width', 1.5);
    lbl(gs, xLeft, rowY - cardH / 2 + 26, 'LayerNorm', { size: 13, weight: '700', color: COLORS.layernorm.stroke });
    lbl(gs, xLeft, rowY - 6, 'Transformers, RNNs', { size: 11, color: 'var(--text)' });
    lbl(gs, xLeft, rowY + 18, 'per-sample stats, batch-independent', { size: 9, color: 'var(--text-muted)', font: 'monospace' });
    lbl(gs, xLeft, rowY + 38, 'BERT, GPT, ViT', { size: 9, color: COLORS.layernorm.stroke, font: 'monospace' });

    gs.append('rect').attr('x', xMid - cardW / 2).attr('y', rowY - cardH / 2).attr('width', cardW).attr('height', cardH)
      .attr('rx', 8).attr('fill', COLORS.rmsnorm.fill).attr('stroke', COLORS.rmsnorm.stroke).attr('stroke-width', 1.5);
    lbl(gs, xMid, rowY - cardH / 2 + 26, 'RMSNorm', { size: 13, weight: '700', color: COLORS.rmsnorm.stroke });
    lbl(gs, xMid, rowY - 6, 'Modern LLMs', { size: 11, color: 'var(--text)' });
    lbl(gs, xMid, rowY + 18, '33% fewer ops, no mean subtraction', { size: 9, color: 'var(--text-muted)', font: 'monospace' });
    lbl(gs, xMid, rowY + 38, 'LLaMA, Gemma, Mistral', { size: 9, color: COLORS.rmsnorm.stroke, font: 'monospace' });

    gs.append('rect').attr('x', xRight - cardW / 2).attr('y', rowY - cardH / 2).attr('width', cardW).attr('height', cardH)
      .attr('rx', 8).attr('fill', COLORS.batchnorm.fill).attr('stroke', COLORS.batchnorm.stroke).attr('stroke-width', 1.5);
    lbl(gs, xRight, rowY - cardH / 2 + 26, 'BatchNorm', { size: 13, weight: '700', color: COLORS.batchnorm.stroke });
    lbl(gs, xRight, rowY - 6, 'CNNs, image models', { size: 11, color: 'var(--text)' });
    lbl(gs, xRight, rowY + 18, 'batch-dependent, running stats at inference', { size: 9, color: 'var(--text-muted)', font: 'monospace' });
    lbl(gs, xRight, rowY + 38, 'ResNet, EfficientNet', { size: 9, color: COLORS.batchnorm.stroke, font: 'monospace' });

    shapeEq(gs, CX, rowY + cardH / 2 + SHAPE_GAP + 10,
      `output shape: [${seqLen}, ${dModel}] (same as input)`, COLORS.output.stroke);
    y = rowY + cardH / 2 + SHAPE_GAP + 50 + STEP_GAP;
    steps.push(makeStep(stepId, 'Usage', 'Usage Summary',
      'LayerNorm vs RMSNorm vs BatchNorm use cases',
      'Each normalization method is suited to different architectures and batch settings.', 'step-usage',
      COLORS.output.stroke, COLORS.output.fill));
  }

  return { steps, y };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Norm dimensions variant
// ═══════════════════════════════════════════════════════════════════════════════

function renderNormDims(
  g: Gsel, yStart: number, seqLen: number, dModel: number
): { steps: NCStep[]; y: number } {
  const steps: NCStep[] = [];
  let y = yStart;

  // Step 1: Input with Axis Labels
  {
    const stepId = 1;
    const gs = startGroup(g, 'step-input-axes', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Input with Axis Labels', `x [${seqLen}, ${dModel}]`,
      COLORS.input.fill, COLORS.input.stroke);
    const rowY = hBottom + BOX_TO_ROW;
    const gridW = GRID_COLS * CELL;
    const gridH = GRID_ROWS * CELL;
    const x0 = CX - gridW / 2;
    const y0 = rowY - gridH / 2;

    drawInputGrid(gs, CX, rowY, GRID_ROWS, GRID_COLS, CELL, SAMPLE_MATRIX, COLORS.input.stroke);
    lbl(gs, CX, y0 - 28, 'd_model →', { size: 11, weight: '600', color: 'var(--text-muted)' });
    lbl(gs, x0 - 22, rowY, 'seq_len ↓', { size: 11, weight: '600', color: 'var(--text-muted)', anchor: 'end' });

    // Highlight row 2
    const rowY2 = y0 + 2 * CELL;
    g.append('rect').attr('x', x0 - 2).attr('y', rowY2 - 2).attr('width', gridW + 4).attr('height', CELL)
      .attr('fill', 'none').attr('stroke', COLORS.layernorm.stroke).attr('stroke-width', 2.5).attr('rx', 2);
    lbl(gs, x0 + gridW + 12, rowY2 + CELL / 2, 't=2 (LN/RMS row)', { size: 9, color: COLORS.layernorm.stroke, anchor: 'start' });

    // Highlight col 3
    const colX3 = x0 + 3 * CELL;
    g.append('rect').attr('x', colX3 - 2).attr('y', y0 - 2).attr('width', CELL).attr('height', gridH + 4)
      .attr('fill', 'none').attr('stroke', COLORS.batchnorm.stroke).attr('stroke-width', 2.5).attr('rx', 2);
    lbl(gs, colX3 + CELL / 2, y0 + gridH + 22, 'd=3 (BN column)', { size: 9, color: COLORS.batchnorm.stroke });

    shapeEq(gs, CX, rowY + gridH / 2 + SHAPE_GAP,
      'x [4, 7] sample — row 2 & col 3 highlighted', COLORS.input.stroke);
    y = rowY + gridH / 2 + SHAPE_GAP + 36 + STEP_GAP;
    steps.push(makeStep(stepId, 'Input', 'Input with Axis Labels', `x [${seqLen}, ${dModel}]`,
      'Input matrix with row (token) and column (feature) axes highlighted.', 'step-input-axes',
      COLORS.input.stroke, COLORS.input.fill));
  }

  // Step 2: LayerNorm path
  {
    const stepId = 2;
    const gs = startGroup(g, 'step-layernorm', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'LayerNorm Path',
      'μ = mean(x_t), σ² = var(x_t), x̂ = (x-μ)/√(σ²+ε)', COLORS.layernorm.fill, COLORS.layernorm.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    const x0 = CX - 420;
    const x1 = CX - 280;
    const x2 = CX - 140;
    const x3 = CX;
    const x4 = CX + 140;
    const x5 = CX + 280;
    const x6 = CX + 420;

    drawValueGrid(gs, x0, rowY, 1, GRID_COLS, SMALL_CELL, LN_ROW.values, identityFn,
      COLORS.input.stroke, COLORS.input.stroke);
    lbl(gs, x0, rowY - SMALL_CELL / 2 - 14, 'x_t', { size: 10, weight: '600', color: COLORS.input.stroke });

    opBox(gs, x1, rowY, 'mean(·)', COLORS.layernorm.stroke);
    scalarBlock(gs, x2, rowY, 'μ=-0.54', 'mean', COLORS.layernorm.stroke);
    opBox(gs, x3, rowY, '(x-μ)', COLORS.layernorm.stroke);
    scalarBlock(gs, x4, rowY, 'σ²=0.73', 'var', COLORS.variance.stroke);
    opBox(gs, x5, rowY, '/√(σ²+ε)', COLORS.layernorm.stroke);
    drawValueGrid(gs, x6, rowY, 1, GRID_COLS, SMALL_CELL, LN_ROW.xhat, identityFn,
      COLORS.layernorm.stroke, COLORS.layernorm.stroke, 2);
    lbl(gs, x6, rowY - SMALL_CELL / 2 - 14, 'x̂', { size: 10, weight: '600', color: COLORS.layernorm.stroke });

    arrowH(gs, x0, x1, rowY, COLORS.layernorm.stroke);
    arrowH(gs, x1, x2, rowY, COLORS.layernorm.stroke);
    arrowH(gs, x2, x3, rowY, COLORS.layernorm.stroke);
    arrowH(gs, x3, x4, rowY, COLORS.variance.stroke);
    arrowH(gs, x4, x5, rowY, COLORS.layernorm.stroke);
    arrowH(gs, x5, x6, rowY, COLORS.layernorm.stroke);

    sampleNote(gs, CX, rowY + SMALL_CELL / 2 + 34,
      'μ = -0.54, σ² = 0.73 (row 2 stats) | 2×d_model params (γ+β)', COLORS.layernorm.stroke);

    const outY = rowY + SMALL_CELL / 2 + 90;
    opBox(gs, CX, outY, 'γ·x̂+β', COLORS.scale.stroke);
    drawValueGrid(gs, CX + 160, outY, 1, GRID_COLS, SMALL_CELL, LN_ROW.output, identityFn,
      COLORS.output.stroke, COLORS.output.stroke, 2);
    lbl(gs, CX + 160, outY - SMALL_CELL / 2 - 14, 'LayerNorm(x_t)', { size: 10, weight: '600', color: COLORS.output.stroke });
    arrowH(gs, CX, CX + 160, outY, COLORS.scale.stroke);

    shapeEq(gs, CX, outY + SMALL_CELL / 2 + SHAPE_GAP,
      'out_LN = γ·((x-μ)/√(σ²+ε)) + β', COLORS.layernorm.stroke);
    y = outY + SMALL_CELL / 2 + SHAPE_GAP + 40 + STEP_GAP;
    steps.push(makeStep(stepId, 'LayerNorm', 'LayerNorm Path',
      'μ = mean(x_t), σ² = var(x_t), out = γ·x̂+β',
      'LayerNormalizes each token row independently.', 'step-layernorm',
      COLORS.layernorm.stroke, COLORS.layernorm.fill));
  }

  // Step 3: RMSNorm path
  {
    const stepId = 3;
    const gs = startGroup(g, 'step-rmsnorm', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'RMSNorm Path',
      'RMS = √(mean(x²)+ε), x̂ = x/RMS', COLORS.rmsnorm.fill, COLORS.rmsnorm.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    // Key annotation at top so it never overlaps grids
    gs.append('rect').attr('x', CX - 180).attr('y', rowY - SMALL_CELL / 2 - 52).attr('width', 360).attr('height', 28)
      .attr('rx', 4).attr('fill', COLORS.rmsnorm.fill).attr('stroke', COLORS.rmsnorm.stroke)
      .attr('stroke-width', 1).attr('stroke-dasharray', '4 2');
    lbl(gs, CX, rowY - SMALL_CELL / 2 - 38, 'No mean subtraction — just RMS scaling',
      { size: 10, weight: '600', color: COLORS.rmsnorm.stroke });

    const x0 = CX - 360;
    const x1 = CX - 240;
    const x2 = CX - 120;
    const x3 = CX;
    const x4 = CX + 120;
    const x5 = CX + 240;
    const x6 = CX + 360;

    drawValueGrid(gs, x0, rowY, 1, GRID_COLS, SMALL_CELL, RMS_ROW.values, identityFn,
      COLORS.input.stroke, COLORS.input.stroke);
    lbl(gs, x0, rowY - SMALL_CELL / 2 - 14, 'x_t', { size: 10, weight: '600', color: COLORS.input.stroke });

    opBox(gs, x1, rowY, 'x²', COLORS.rmsnorm.stroke);
    drawValueGrid(gs, x2, rowY, 1, GRID_COLS, SMALL_CELL, RMS_ROW.squared, identityFn,
      COLORS.variance.stroke, COLORS.variance.stroke, 2);
    lbl(gs, x2, rowY - SMALL_CELL / 2 - 14, 'x²', { size: 10, weight: '600', color: COLORS.variance.stroke });

    opBox(gs, x3, rowY, 'mean(·)', COLORS.rmsnorm.stroke);
    scalarBlock(gs, x4, rowY, '1.02', 'mean(x²)', COLORS.rmsnorm.stroke);
    opBox(gs, x5, rowY, '√(·+ε)', COLORS.rmsnorm.stroke);
    scalarBlock(gs, x6, rowY, 'RMS=1.01', 'rms', COLORS.rmsnorm.stroke);

    arrowH(gs, x0, x1, rowY, COLORS.rmsnorm.stroke);
    arrowH(gs, x1, x2, rowY, COLORS.rmsnorm.stroke);
    arrowH(gs, x2, x3, rowY, COLORS.rmsnorm.stroke);
    arrowH(gs, x3, x4, rowY, COLORS.rmsnorm.stroke);
    arrowH(gs, x4, x5, rowY, COLORS.rmsnorm.stroke);
    arrowH(gs, x5, x6, rowY, COLORS.rmsnorm.stroke);

    const outY = rowY + SMALL_CELL / 2 + 100;
    drawValueGrid(gs, CX - 160, outY, 1, GRID_COLS, SMALL_CELL, RMS_ROW.xhat, identityFn,
      COLORS.rmsnorm.stroke, COLORS.rmsnorm.stroke, 2);
    lbl(gs, CX - 160, outY - SMALL_CELL / 2 - 14, 'x̂ = x / RMS', { size: 10, weight: '600', color: COLORS.rmsnorm.stroke });
    opBox(gs, CX, outY, 'γ·x̂', COLORS.scale.stroke);
    drawValueGrid(gs, CX + 160, outY, 1, GRID_COLS, SMALL_CELL, RMS_ROW.output, identityFn,
      COLORS.output.stroke, COLORS.output.stroke, 2);
    lbl(gs, CX + 160, outY - SMALL_CELL / 2 - 14, 'RMSNorm(x_t)', { size: 10, weight: '600', color: COLORS.output.stroke });

    arrowL(gs, x6, rowY, CX - 160, outY, COLORS.rmsnorm.stroke, 8);
    arrowH(gs, CX - 160, CX, outY, COLORS.rmsnorm.stroke);
    arrowH(gs, CX, CX + 160, outY, COLORS.scale.stroke);

    sampleNote(gs, CX, outY + SMALL_CELL / 2 + 34,
      'd_model params (γ only) — 33% fewer than LayerNorm', COLORS.rmsnorm.stroke);

    shapeEq(gs, CX, outY + SMALL_CELL / 2 + SHAPE_GAP + 30,
      'out_RMS = γ·(x / RMS(x))', COLORS.rmsnorm.stroke);
    y = outY + SMALL_CELL / 2 + SHAPE_GAP + 70 + STEP_GAP;
    steps.push(makeStep(stepId, 'RMSNorm', 'RMSNorm Path',
      'RMS = √(mean(x²)+ε), out = γ·x̂',
      'RMSNorm skips mean-centering and divides by root-mean-square.', 'step-rmsnorm',
      COLORS.rmsnorm.stroke, COLORS.rmsnorm.fill));
  }

  // Step 4: BatchNorm path
  {
    const stepId = 4;
    const gs = startGroup(g, 'step-batchnorm', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'BatchNorm Path (transposed)',
      'μ_B = mean_B(x_d), normalize over batch/seq', COLORS.batchnorm.fill, COLORS.batchnorm.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    // Warning note at top so it never overlaps grids
    gs.append('rect').attr('x', CX - 180).attr('y', rowY - 82).attr('width', 360).attr('height', 28)
      .attr('rx', 4).attr('fill', '#fff').attr('stroke', '#ef4444').attr('stroke-width', 1).attr('stroke-dasharray', '4 2');
    lbl(gs, CX, rowY - 68, 'Batch-dependent! Requires running mean/var at inference',
      { size: 10, weight: '600', color: '#ef4444' });

    const cellSize = 28;
    const x0 = CX - 400;
    const x1 = CX - 280;
    const x2 = CX - 160;
    const x3 = CX - 40;
    const x4 = CX + 80;
    const x5 = CX + 200;
    const x6 = CX + 320;
    const x7 = CX + 440;

    drawValueGrid(gs, x0, rowY, 4, 1, cellSize, BN_COL.values, identityFn,
      COLORS.input.stroke, COLORS.input.stroke);
    lbl(gs, x0, rowY - cellSize * 2 - 14, 'x[:,3]', { size: 10, weight: '600', color: COLORS.input.stroke });
    smallNote(gs, x0, rowY + cellSize * 2 + 18, 'one feature across seq', COLORS.input.stroke, 'middle');

    opBox(gs, x1, rowY, 'mean_B(·)', COLORS.batchnorm.stroke);
    scalarBlock(gs, x2, rowY, 'μ_B=-0.55', 'mean', COLORS.batchnorm.stroke);
    opBox(gs, x3, rowY, '(x-μ_B)', COLORS.batchnorm.stroke);
    drawValueGrid(gs, x4, rowY, 4, 1, cellSize, BN_COL.centered, identityFn,
      COLORS.batchnorm.stroke, COLORS.batchnorm.stroke, 2);
    opBox(gs, x5, rowY, 'var_B(·)', COLORS.variance.stroke);
    scalarBlock(gs, x6, rowY, 'σ²_B=0.53', 'var', COLORS.variance.stroke);
    opBox(gs, x7, rowY, '/√(σ²_B+ε)', COLORS.batchnorm.stroke);

    arrowH(gs, x0, x1, rowY, COLORS.batchnorm.stroke);
    arrowH(gs, x1, x2, rowY, COLORS.batchnorm.stroke);
    arrowH(gs, x2, x3, rowY, COLORS.batchnorm.stroke);
    arrowH(gs, x3, x4, rowY, COLORS.batchnorm.stroke);
    arrowH(gs, x4, x5, rowY, COLORS.variance.stroke);
    arrowH(gs, x5, x6, rowY, COLORS.variance.stroke);
    arrowH(gs, x6, x7, rowY, COLORS.batchnorm.stroke);

    const outY = rowY + cellSize * 2 + 100;
    drawValueGrid(gs, CX - 120, outY, 4, 1, cellSize, BN_COL.xhat, identityFn,
      COLORS.batchnorm.stroke, COLORS.batchnorm.stroke, 2);
    lbl(gs, CX - 120, outY - cellSize * 2 - 14, 'x̂', { size: 10, weight: '600', color: COLORS.batchnorm.stroke });
    opBox(gs, CX, outY, 'γ·x̂+β', COLORS.scale.stroke);
    drawValueGrid(gs, CX + 120, outY, 4, 1, cellSize, BN_COL.output, identityFn,
      COLORS.output.stroke, COLORS.output.stroke, 2);
    lbl(gs, CX + 120, outY - cellSize * 2 - 14, 'BN(x[:,3])', { size: 10, weight: '600', color: COLORS.output.stroke });

    arrowL(gs, x7, rowY, CX - 120, outY, COLORS.batchnorm.stroke, 8);
    arrowH(gs, CX - 120, CX, outY, COLORS.batchnorm.stroke);
    arrowH(gs, CX, CX + 120, outY, COLORS.scale.stroke);

    sampleNote(gs, CX, outY + cellSize * 2 + 34,
      'Transpose back → [seq_len, d_model]', COLORS.batchnorm.stroke);

    shapeEq(gs, CX, outY + cellSize * 2 + SHAPE_GAP + 30,
      'out_BN = γ·((x-μ_B)/√(σ²_B+ε)) + β', COLORS.batchnorm.stroke);
    y = outY + cellSize * 2 + SHAPE_GAP + 70 + STEP_GAP;
    steps.push(makeStep(stepId, 'BatchNorm', 'BatchNorm Path (transposed)',
      'μ_B = mean_B(x_d), out = γ·x̂+β',
      'BatchNorm normalizes each feature column across the batch/sequence.', 'step-batchnorm',
      COLORS.batchnorm.stroke, COLORS.batchnorm.fill));
  }

  // Step 5: Output Comparison
  {
    const stepId = 5;
    const gs = startGroup(g, 'step-output', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Output Comparison',
      'all norms output [seq_len, d_model]', COLORS.output.fill, COLORS.output.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    const cellSize = SMALL_CELL;
    const xLeft = CX - 360;
    const xMid = CX;
    const xRight = CX + 360;

    drawValueGrid(gs, xLeft, rowY, 1, GRID_COLS, cellSize, LN_ROW.output, identityFn,
      COLORS.layernorm.stroke, COLORS.layernorm.stroke, 2);
    lbl(gs, xLeft, rowY - cellSize / 2 - 24, 'LayerNorm(x)', { size: 11, weight: '600', color: COLORS.layernorm.stroke });

    drawValueGrid(gs, xMid, rowY, 1, GRID_COLS, cellSize, RMS_ROW.output, identityFn,
      COLORS.rmsnorm.stroke, COLORS.rmsnorm.stroke, 2);
    lbl(gs, xMid, rowY - cellSize / 2 - 24, 'RMSNorm(x)', { size: 11, weight: '600', color: COLORS.rmsnorm.stroke });

    drawValueGrid(gs, xRight, rowY, 4, 1, cellSize, BN_COL.output, identityFn,
      COLORS.batchnorm.stroke, COLORS.batchnorm.stroke, 2);
    lbl(gs, xRight, rowY - cellSize * 2 - 24, 'BatchNorm(x)', { size: 11, weight: '600', color: COLORS.batchnorm.stroke });

    shapeEq(gs, CX, rowY + cellSize * 2 + SHAPE_GAP + 10,
      'different normalization axes → different outputs', COLORS.output.stroke);
    y = rowY + cellSize * 2 + SHAPE_GAP + 50 + STEP_GAP;
    steps.push(makeStep(stepId, 'Output', 'Output Comparison',
      'LayerNorm vs RMSNorm vs BatchNorm outputs',
      'Same input produces different outputs because each norm reduces over different axes.', 'step-output',
      COLORS.output.stroke, COLORS.output.fill));
  }

  return { steps, y };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Training dynamics variant
// ═══════════════════════════════════════════════════════════════════════════════

function renderTrainingDynamics(
  g: Gsel, yStart: number, seqLen: number, dModel: number
): { steps: NCStep[]; y: number } {
  const steps: NCStep[] = [];
  let y = yStart;

  // Step 1: Input Activations
  {
    const stepId = 1;
    const gs = startGroup(g, 'step-input-train', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Input Activations', `x [${seqLen}, ${dModel}]`,
      COLORS.input.fill, COLORS.input.stroke);
    const rowY = hBottom + BOX_TO_ROW;
    const gridH = GRID_ROWS * CELL;
    lbl(gs, CX, rowY - gridH / 2 - 20, 'x', { size: 12, weight: '700', color: COLORS.input.stroke });
    drawInputGrid(gs, CX, rowY, GRID_ROWS, GRID_COLS, CELL, SAMPLE_MATRIX, COLORS.input.stroke);
    smallNote(gs, CX + GRID_COLS * CELL / 2 + 14, rowY - 16, 'blue = positive', COLORS.input.stroke, 'start');
    smallNote(gs, CX + GRID_COLS * CELL / 2 + 14, rowY + 4, 'orange = negative', '#f97316', 'start');
    shapeEq(gs, CX, rowY + gridH / 2 + SHAPE_GAP, `x [${seqLen}, ${dModel}]`, COLORS.input.stroke);
    sampleNote(gs, CX, rowY + gridH / 2 + SHAPE_GAP + 36,
      'input to training step — same x for all 3 norm paths', COLORS.input.stroke);
    y = rowY + gridH / 2 + SHAPE_GAP + 60 + STEP_GAP;
    steps.push(makeStep(stepId, 'Input', 'Input Activations', `x [${seqLen}, ${dModel}]`,
      'Input hidden states shared by all normalization paths during training.', 'step-input-train',
      COLORS.input.stroke, COLORS.input.fill));
  }

  // Step 2: First Norm Step
  {
    const stepId = 2;
    const gs = startGroup(g, 'step-first-norm', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'First Norm Step',
      'LayerNorm | RMSNorm | BatchNorm', COLORS.layernorm.fill, COLORS.layernorm.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    const xLeft = CX - 380;
    const xMid = CX;
    const xRight = CX + 380;
    const colW = 300;
    const cellSize = 22;

    [xLeft, xMid, xRight].forEach((cx, i) => {
      const color = i === 0 ? COLORS.layernorm.stroke : i === 1 ? COLORS.rmsnorm.stroke : COLORS.batchnorm.stroke;
      const fill = i === 0 ? COLORS.layernorm.fill : i === 1 ? COLORS.rmsnorm.fill : COLORS.batchnorm.fill;
      const name = i === 0 ? 'LayerNorm' : i === 1 ? 'RMSNorm' : 'BatchNorm';
      gs.append('rect').attr('x', cx - colW / 2).attr('y', rowY - 120).attr('width', colW).attr('height', 240)
        .attr('rx', 8).attr('fill', fill).attr('stroke', color).attr('stroke-width', 1.5).attr('opacity', 0.15);
      lbl(gs, cx, rowY - 100, name + ' path', { size: 12, weight: '700', color });

      const inY = rowY - 54;
      const outY = rowY + 54;
      drawInputGrid(gs, cx, inY, 3, 5, cellSize, SAMPLE_MATRIX, COLORS.input.stroke);
      opBox(gs, cx, rowY, name === 'LayerNorm' ? 'LN(·)' : name === 'RMSNorm' ? 'RMS(·)' : 'BN(·)', color);
      drawValueGrid(gs, cx, outY, 3, 5, cellSize, SAMPLE_MATRIX,
        name === 'RMSNorm' ? (v: number) => v / 1.2 : identityFn, color, color);

      arrowV(gs, cx, inY, rowY, color);
      arrowV(gs, cx, rowY, outY, color);
    });

    shapeEq(gs, CX, rowY + 130,
      '3 parallel norm paths — same input, different statistics', COLORS.layernorm.stroke);
    sampleNote(gs, CX, rowY + 130 + 42,
      'LN/RMS: per-sample stats | BN: batch stats (running)', COLORS.layernorm.stroke);
    y = rowY + 130 + 70 + STEP_GAP;
    steps.push(makeStep(stepId, 'First Norm', 'First Norm Step',
      'LayerNorm | RMSNorm | BatchNorm on same input',
      'Each normalization path processes the same input using its own statistics.', 'step-first-norm',
      COLORS.layernorm.stroke, COLORS.layernorm.fill));
  }

  // Step 3: Linear + GELU + Dropout
  {
    const stepId = 3;
    const gs = startGroup(g, 'step-post-norm', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Linear + GELU + Dropout',
      'h = dropout(gelu(W · norm(x)))', COLORS.input.fill, COLORS.input.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    const xLeft = CX - 380;
    const xMid = CX;
    const xRight = CX + 380;
    const colW = 320;

    [xLeft, xMid, xRight].forEach((cx, i) => {
      const color = i === 0 ? COLORS.layernorm.stroke : i === 1 ? COLORS.rmsnorm.stroke : COLORS.batchnorm.stroke;
      gs.append('rect').attr('x', cx - colW / 2).attr('y', rowY - 140).attr('width', colW).attr('height', 280)
        .attr('rx', 8).attr('fill', '#fff').attr('stroke', color).attr('stroke-width', 1.5);

      const y0 = rowY - 100;
      const y1 = rowY - 34;
      const y2 = rowY + 34;
      const y3 = rowY + 100;
      opBox(gs, cx, y0, 'W·(·)', color);
      opBox(gs, cx, y1, 'GELU(·)', color);
      opBox(gs, cx, y2, 'Dropout(·)', color);
      opBox(gs, cx, y3, 'h', color);

      arrowV(gs, cx, y0, y1, color);
      arrowV(gs, cx, y1, y2, color);
      arrowV(gs, cx, y2, y3, color);
    });

    shapeEq(gs, CX, rowY + 160,
      'h = dropout(gelu(W · norm(x))) — each path processes independently', COLORS.input.stroke);
    sampleNote(gs, CX, rowY + 160 + 42, 'dropout p=0.1 — same mask rate for all paths', COLORS.input.stroke);
    y = rowY + 160 + 70 + STEP_GAP;
    steps.push(makeStep(stepId, 'Post-Norm', 'Linear + GELU + Dropout',
      'h = dropout(gelu(W · norm(x)))',
      'Each normalized path continues through the same downstream layers.', 'step-post-norm',
      COLORS.input.stroke, COLORS.input.fill));
  }

  // Step 4: Second Norm Step — Stats Update
  {
    const stepId = 4;
    const gs = startGroup(g, 'step-stats', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Second Norm Step — Stats Update',
      'BN: EMA update | LN/RMS: per-sample', COLORS.variance.fill, COLORS.variance.stroke);
    const rowY = hBottom + BOX_TO_ROW;

    const xLeft = CX - 380;
    const xMid = CX;
    const xRight = CX + 360;
    const colW = 300;

    // LayerNorm column
    gs.append('rect').attr('x', xLeft - colW / 2).attr('y', rowY - 130).attr('width', colW).attr('height', 260)
      .attr('rx', 8).attr('fill', COLORS.layernorm.fill).attr('stroke', COLORS.layernorm.stroke).attr('stroke-width', 1.5).attr('opacity', 0.15);
    lbl(gs, xLeft, rowY - 110, 'LayerNorm', { size: 12, weight: '700', color: COLORS.layernorm.stroke });
    opBox(gs, xLeft, rowY - 50, 'μ, σ²', COLORS.layernorm.stroke);
    opBox(gs, xLeft, rowY + 20, 'LN(·)', COLORS.layernorm.stroke);
    arrowV(gs, xLeft, rowY - 50, rowY + 20, COLORS.layernorm.stroke);
    lbl(gs, xLeft, rowY + 80, 'computed per-sample (fresh)', { size: 9, color: 'var(--text-muted)', font: 'monospace' });
    lbl(gs, xLeft, rowY + 96, 'no running state', { size: 9, color: 'var(--text-muted)', font: 'monospace' });

    // RMSNorm column
    gs.append('rect').attr('x', xMid - colW / 2).attr('y', rowY - 130).attr('width', colW).attr('height', 260)
      .attr('rx', 8).attr('fill', COLORS.rmsnorm.fill).attr('stroke', COLORS.rmsnorm.stroke).attr('stroke-width', 1.5).attr('opacity', 0.15);
    lbl(gs, xMid, rowY - 110, 'RMSNorm', { size: 12, weight: '700', color: COLORS.rmsnorm.stroke });
    opBox(gs, xMid, rowY - 50, 'RMS', COLORS.rmsnorm.stroke);
    opBox(gs, xMid, rowY + 20, 'RMS(·)', COLORS.rmsnorm.stroke);
    arrowV(gs, xMid, rowY - 50, rowY + 20, COLORS.rmsnorm.stroke);
    lbl(gs, xMid, rowY + 80, 'computed per-sample (fresh)', { size: 9, color: 'var(--text-muted)', font: 'monospace' });
    lbl(gs, xMid, rowY + 96, 'no running state', { size: 9, color: 'var(--text-muted)', font: 'monospace' });

    // BatchNorm column
    gs.append('rect').attr('x', xRight - colW / 2).attr('y', rowY - 180).attr('width', colW).attr('height', 380)
      .attr('rx', 8).attr('fill', COLORS.batchnorm.fill).attr('stroke', COLORS.batchnorm.stroke).attr('stroke-width', 1.5).attr('opacity', 0.15);
    lbl(gs, xRight, rowY - 160, 'BatchNorm', { size: 12, weight: '700', color: COLORS.batchnorm.stroke });

    const yMean = rowY - 120;
    const yVar = rowY + 70;
    scalarBlock(gs, xRight - 75, yMean, 'batch_mean', 'new', COLORS.batchnorm.stroke);
    scalarBlock(gs, xRight + 75, yMean, 'running_mean', 'old', '#94a3b8');
    opBox(gs, xRight, yMean + 60, 'α·new + (1-α)·old', COLORS.batchnorm.stroke);
    scalarBlock(gs, xRight, yMean + 120, 'running_mean', 'updated', COLORS.batchnorm.stroke);

    scalarBlock(gs, xRight - 75, yVar, 'batch_var', 'new', COLORS.variance.stroke);
    scalarBlock(gs, xRight + 75, yVar, 'running_var', 'old', '#94a3b8');
    opBox(gs, xRight, yVar + 60, 'α·new + (1-α)·old', COLORS.variance.stroke);
    scalarBlock(gs, xRight, yVar + 120, 'running_var', 'updated', COLORS.variance.stroke);

    arrowV(gs, xRight - 75, yMean + 24, yMean + 42, COLORS.batchnorm.stroke, 4);
    arrowV(gs, xRight + 75, yMean + 24, yMean + 42, '#94a3b8', 4);
    arrowV(gs, xRight, yMean + 84, yMean + 96, COLORS.batchnorm.stroke, 4);
    arrowV(gs, xRight - 75, yVar + 24, yVar + 42, COLORS.variance.stroke, 4);
    arrowV(gs, xRight + 75, yVar + 24, yVar + 42, '#94a3b8', 4);
    arrowV(gs, xRight, yVar + 84, yVar + 96, COLORS.variance.stroke, 4);

    // Contrast box
    gs.append('rect').attr('x', CX - 260).attr('y', rowY + 210).attr('width', 520).attr('height', 32)
      .attr('rx', 4).attr('fill', '#fff').attr('stroke', '#7b1fa2').attr('stroke-width', 1.5).attr('stroke-dasharray', '4 2');
    lbl(gs, CX, rowY + 227, 'LN/RMS: mode-independent | BN: mode-dependent (train vs eval)',
      { size: 10, weight: '600', color: '#7b1fa2' });

    shapeEq(gs, CX, rowY + 270,
      'BN: running stats via EMA | LN/RMS: per-sample stats every forward pass', COLORS.variance.stroke);
    y = rowY + 270 + 36 + STEP_GAP;
    steps.push(makeStep(stepId, 'Stats', 'Second Norm Step — Stats Update',
      'BatchNorm EMA vs LayerNorm/RMSNorm per-sample stats',
      'LayerNorm and RMSNorm compute fresh statistics per sample; BatchNorm maintains running statistics via EMA.', 'step-stats',
      COLORS.variance.stroke, COLORS.variance.fill));
  }

  // Step 5: Training Behavior Summary
  {
    const stepId = 5;
    const gs = startGroup(g, 'step-summary', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Training Behavior Summary',
      'when to use each norm during training', COLORS.output.fill, COLORS.output.stroke);
    const rowY = hBottom + BOX_TO_ROW;
    const cardW = 340;
    const cardH = 160;
    const xLeft = CX - 380;
    const xMid = CX;
    const xRight = CX + 380;

    gs.append('rect').attr('x', xLeft - cardW / 2).attr('y', rowY - cardH / 2).attr('width', cardW).attr('height', cardH)
      .attr('rx', 8).attr('fill', COLORS.layernorm.fill).attr('stroke', COLORS.layernorm.stroke).attr('stroke-width', 1.5);
    lbl(gs, xLeft, rowY - cardH / 2 + 28, 'LayerNorm', { size: 13, weight: '700', color: COLORS.layernorm.stroke });
    lbl(gs, xLeft, rowY - 10, 'Per-sample stats, no running state', { size: 10.5, color: 'var(--text)' });
    lbl(gs, xLeft, rowY + 14, 'batch-independent, train/eval identical', { size: 10, color: 'var(--text-muted)', font: 'monospace' });
    lbl(gs, xLeft, rowY + 38, 'Used in: BERT, GPT, ViT', { size: 10, color: COLORS.layernorm.stroke, font: 'monospace' });

    gs.append('rect').attr('x', xMid - cardW / 2).attr('y', rowY - cardH / 2).attr('width', cardW).attr('height', cardH)
      .attr('rx', 8).attr('fill', COLORS.rmsnorm.fill).attr('stroke', COLORS.rmsnorm.stroke).attr('stroke-width', 1.5);
    lbl(gs, xMid, rowY - cardH / 2 + 28, 'RMSNorm', { size: 13, weight: '700', color: COLORS.rmsnorm.stroke });
    lbl(gs, xMid, rowY - 10, 'Per-sample RMS, no running state', { size: 10.5, color: 'var(--text)' });
    lbl(gs, xMid, rowY + 14, '33% fewer ops, train/eval identical', { size: 10, color: 'var(--text-muted)', font: 'monospace' });
    lbl(gs, xMid, rowY + 38, 'Used in: LLaMA, Gemma, Mistral', { size: 10, color: COLORS.rmsnorm.stroke, font: 'monospace' });

    gs.append('rect').attr('x', xRight - cardW / 2).attr('y', rowY - cardH / 2).attr('width', cardW).attr('height', cardH)
      .attr('rx', 8).attr('fill', COLORS.batchnorm.fill).attr('stroke', COLORS.batchnorm.stroke).attr('stroke-width', 1.5);
    lbl(gs, xRight, rowY - cardH / 2 + 28, 'BatchNorm', { size: 13, weight: '700', color: COLORS.batchnorm.stroke });
    lbl(gs, xRight, rowY - 10, 'Batch stats + EMA running state', { size: 10.5, color: 'var(--text)' });
    lbl(gs, xRight, rowY + 14, 'mode-dependent, train/eval differ', { size: 10, color: 'var(--text-muted)', font: 'monospace' });
    lbl(gs, xRight, rowY + 38, 'Used in: ResNet, CNNs', { size: 10, color: COLORS.batchnorm.stroke, font: 'monospace' });

    shapeEq(gs, CX, rowY + cardH / 2 + SHAPE_GAP + 10,
      'LN/RMS: mode-independent | BN: mode-dependent (train vs eval)', COLORS.output.stroke);
    y = rowY + cardH / 2 + SHAPE_GAP + 50 + STEP_GAP;
    steps.push(makeStep(stepId, 'Summary', 'Training Behavior Summary',
      'LayerNorm vs RMSNorm vs BatchNorm training behavior',
      'Compare how each normalization method handles training dynamics and inference mode.', 'step-summary',
      COLORS.output.stroke, COLORS.output.fill));
  }

  return { steps, y };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Main export
// ═══════════════════════════════════════════════════════════════════════════════

export function renderNormComparisonDetailed(
  g: Gsel,
  params: Record<string, number | string>,
  _meta: ComponentDef,
  _graph: ComputationGraph
): { width: number; height: number; steps: StepInfo[] } {
  const seqLen = Number(params.seq_len) || 128;
  const dModel = Number(params.d_model) || 512;
  const variant = String(params.variant || 'overview') as NCVariant;

  const stepsMeta: NCStep[] = [];
  let y = 10;

  lbl(g, CX, y + 14, 'Norm Comparison', { size: 18, weight: '700', color: 'var(--text)' });
  y += 36;
  const variantLabel = variant === 'norm_dims'
    ? 'Normalization Dimensions'
    : variant === 'training_dynamics'
      ? 'Training Dynamics'
      : 'Overview (comparison)';
  lbl(g, CX, y + 8,
    `${variantLabel} — LayerNorm vs RMSNorm vs BatchNorm`,
    { size: 10, color: 'var(--text-muted)' });
  y += 30;

  y = paramSummary(g, CX, y, [
    `seq_len: ${seqLen}`, `d_model: ${dModel}`, `variant: ${variant.toUpperCase()}`,
  ]);
  y += 32;

  const { steps, y: finalY } = variant === 'norm_dims'
    ? renderNormDims(g, y, seqLen, dModel)
    : variant === 'training_dynamics'
      ? renderTrainingDynamics(g, y, seqLen, dModel)
      : renderOverview(g, y, seqLen, dModel);
  stepsMeta.push(...steps);
  y = finalY;

  // ── Footer ─────────────────────────────────────────────────────────────────
  y += FOOTER_PAD;

  const insightText = variant === 'norm_dims'
    ? 'The normalization axis is the key differentiator. LayerNorm and RMSNorm normalize over d_model (per token, row-wise) — this makes them batch-independent. BatchNorm normalizes over the batch/sequence dimension (per feature, column-wise) — this couples statistics across samples and requires running mean/variance at inference. LayerNorm subtracts mean and divides by standard deviation; RMSNorm skips the mean subtraction entirely, saving ~33% of operations.'
    : variant === 'training_dynamics'
      ? 'During training, LayerNorm and RMSNorm compute statistics fresh per forward pass (per-sample, no running state). BatchNorm maintains running mean/variance via exponential moving average: running = α·batch_stat + (1−α)·running. At inference, BatchNorm uses these running statistics; LayerNorm and RMSNorm still compute per-sample. This makes BatchNorm inference-mode dependent (train vs eval) while LayerNorm and RMSNorm are mode-independent.'
      : 'Normalization stabilizes training by controlling activation distributions. LayerNorm computes per-sample statistics across features (d_model), making it batch-independent and ideal for Transformers. RMSNorm skips the mean subtraction, dividing only by the root-mean-square, saving ~33% of operations with comparable quality — used by LLaMA, Gemma, and modern LLMs. BatchNorm computes statistics across the batch dimension per feature, requiring running mean/variance tracking at inference — effective in CNNs but problematic for variable-length sequences.';

  y = drawExplanation(g as Sel, CX - (W - 160) / 2, y, W - 160, insightText, 'insight');
  y += 24;

  const perfText = variant === 'norm_dims'
    ? `Input shape [${seqLen}, ${dModel}]. Computing μ and σ² requires 2 passes over d_model (LayerNorm) or 1 pass for RMS (RMSNorm). BatchNorm requires storing running statistics (2×${dModel} extra memory for EMA buffers). Sample row 2: μ=-0.54, σ²=0.73, RMS=1.01. All norms are O(seq×d_model) per forward pass.`
    : variant === 'training_dynamics'
      ? `Input shape [${seqLen}, ${dModel}]. BatchNorm: extra memory for running_mean and running_var buffers (2×${dModel}) plus EMA update compute per step. LayerNorm/RMSNorm: no running state, simpler implementation. All norms add O(seq×d_model) compute per forward pass. LayerNorm: 2×${dModel} params; RMSNorm: ${dModel} params; BatchNorm: 2×${dModel} params + running buffers.`
      : `Input shape [${seqLen}, ${dModel}]. LayerNorm: 2×${dModel} parameters (γ+β). RMSNorm: ${dModel} parameters (γ only). BatchNorm: 2×${dModel} parameters + running stats buffers. All are O(seq×d_model) per forward pass.`;

  y = drawExplanation(g as Sel, CX - (W - 160) / 2, y, W - 160, perfText, 'perf');
  y += 24;

  drawComponentLink(g as Sel, CX - (W - 160) / 2, y, (W - 160) / 2 - 8, 56, 'norm', 'Norm (detailed)');
  drawComponentLink(g as Sel, CX + 8, y, (W - 160) / 2 - 8, 56, 'activation-functions', 'Activation Functions');
  y += 80;

  const codeTitle = variant === 'norm_dims'
    ? 'Normalization — Axis Specification (Python)'
    : variant === 'training_dynamics'
      ? 'Normalization — Training Dynamics (Python)'
      : 'Normalization Comparison — Overview (Python)';

  const descLine = variant === 'norm_dims'
    ? 'norm_dims — axis = key differentiator'
    : variant === 'training_dynamics'
      ? 'training_dynamics — train/eval mode handling'
      : 'overview — x[seq_len,d_model] → normalized[seq_len,d_model]';

  const codeText = variant === 'norm_dims'
    ? `# LayerNorm: normalize over last dim (d_model) per token
mu = x.mean(dim=-1, keepdim=True)  # [seq, 1]
var = x.var(dim=-1, keepdim=True, unbiased=False)
x_hat = (x - mu) / torch.sqrt(var + 1e-6)
out = gamma * x_hat + beta

# RMSNorm: same axis, but no mean subtraction
rms = torch.sqrt(x.pow(2).mean(dim=-1, keepdim=True) + 1e-6)
out = gamma * (x / rms)

# BatchNorm: normalize over batch dim (dim=0) per feature
mu_b = x.mean(dim=0, keepdim=True)  # [1, d_model]
var_b = x.var(dim=0, keepdim=True, unbiased=False)
out = gamma * (x - mu_b) / torch.sqrt(var_b + 1e-5) + beta`
    : variant === 'training_dynamics'
      ? `# LayerNorm/RMSNorm: no train/eval difference
out = layernorm(x)  # same in train and eval

# BatchNorm: different behavior in train vs eval
if self.training:
    batch_mean = x.mean(dim=0)
    batch_var = x.var(dim=0)
    # EMA update of running stats
    self.running_mean = 0.1 * batch_mean + 0.9 * self.running_mean
    self.running_var = 0.1 * batch_var + 0.9 * self.running_var
    out = (x - batch_mean) / torch.sqrt(batch_var + 1e-5)
else:
    out = (x - self.running_mean) / torch.sqrt(self.running_var + 1e-5)
out = gamma * out + beta`
      : `# LayerNorm
mu = x.mean(dim=-1, keepdim=True)
var = x.var(dim=-1, keepdim=True, unbiased=False)
x_hat = (x - mu) / torch.sqrt(var + 1e-6)
out_ln = gamma * x_hat + beta

# RMSNorm (LLaMA, Gemma)
rms = torch.sqrt(x.pow(2).mean(dim=-1, keepdim=True) + 1e-6)
out_rms = gamma * (x / rms)

# BatchNorm
mu_b = x.mean(dim=0, keepdim=True)
var_b = x.var(dim=0, keepdim=True, unbiased=False)
out_bn = gamma * (x - mu_b) / torch.sqrt(var_b + 1e-5) + beta`;

  y = drawCodeAnnotation(g as Sel, CX - (W - 160) / 2, y, W - 160,
    codeTitle,
    [descLine],
    codeText.split('\n'));
  y += 32;

  return { width: W, height: y, steps: stepsMeta };
}
